import math

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def lcm_range(start, n):
    res = start
    for i in range(start + 1, start + n):
        res = lcm(res, i)
    return res

def is_weakly_increasing(n, max_k=1000):
    x = [lcm_range(k, n) for k in range(1, max_k + 1)]

    # We check if it is eventually increasing.
    # Since we don't know N, we can't prove it's NOT weakly increasing 
    # just by looking at a few values, unless we find a pattern 
    # or a large number of drops.

    drops = 0
    last_drop_k = 0
    for k in range(len(x) - 1):
        if x[k+1] <= x[k]:
            drops += 1
            last_drop_k = k + 1

    return drops, last_drop_k

for n in range(1, 11):
    drops, last_k = is_weakly_increasing(n)
    print(f"n={n}: drops={drops}, last_drop_k={last_k}")

