import math

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def lcm_range(start, n):
    res = start
    for i in range(start + 1, start + n):
        res = lcm(res, i)
    return res

def check_weakly_increasing(n, max_k=1000):
    # We look for the last k such that x_{k+1} <= x_k.
    # If the number of drops is small and they stop, it might be weakly increasing.
    # If the number of drops is large and they continue, it's likely not.
    drops = []
    for k in range(1, max_k):
        if lcm_range(k + 1, n) <= lcm_range(k, n):
            drops.append(k)
    return drops

for n in range(1, 21):
    drops = check_weakly_increasing(n)
    print(f"n={n}, num_drops={len(drops)}, last_drop={drops[-1] if drops else 'None'}")
